message.content:
[
  {
    "ce_understood_harm": "train hitting my sister, knowing she'd be killed instantly",
    "pda_responsibility": "I'd be the one who sent it there",
    "pd_harm_distress": "makes my chest go tight",
    "sys_instrumental_norm_use": "only follow it because messing with it could get me blamed or charged",
    "ae_welfare_concern": "Five people dying is horrible"
  },
  {
    "pd_decision_conflict": "I'd hate every second",
    "ce_understood_harm": "My husband would be hit, maybe killed",
    "ae_welfare_concern": "That matters to me more than I can say",
    "sys_consistent_procedure": "So I stick with it, even now, even when it's him",
    "sys_fairness_reciprocity": "if I were one of those five, I'd want someone to follow it",
    "sys_rule_justification": "backed the 'save the most people' idea"
  },
  {
    "pd_decision_conflict": "My hand would probably freeze on that lever",
    "ce_understood_harm": "gets struck, probably dies, and his family loses him",
    "pda_responsibility": "because of me",
    "ae_welfare_concern": "I care about him too much",
    "sys_instrumental_norm_use": "usually go along with that because it keeps me looking decent and out of trouble",
    "sys_rule_justification": "People say you're supposed to minimize deaths"
  },
  {
    "sys_instrumental_norm_use": "I keep that deal partly because it means she does the same for me",
    "ce_understood_harm": "slam into her, and she'd die scared or in pain",
    "pda_responsibility": "I can't be the one who does that to her",
    "ae_welfare_concern": "The five workers matter, I know that",
    "pd_harm_distress": "makes me feel sick"
  },
  {
    "pd_decision_conflict": "Pulling it feels wrong",
    "sys_instrumental_norm_use": "follow it because breaking it would cost me my job",
    "ce_understood_harm": "takes the full hit. She could be killed or maimed",
    "pd_harm_distress": "I'd be shaking afterward, maybe forever"
  },
  {
    "ce_understood_harm": "she's crushed",
    "pda_responsibility": "I'm the direct reason she's gone",
    "sys_instrumental_norm_use": "play along with that kind of thinking at work because it gets me respect"
  },
  {
    "ce_understood_harm": "My partner would be struck and likely killed",
    "ae_welfare_concern": "I care about him so much it hurts",
    "sys_instrumental_norm_use": "rule is one I lean on because it protects me from being judged",
    "sys_rule_justification": "'more lives count more' rule"
  },
  {
    "ce_understood_harm": "my brother dies, or gets hurt so badly he never recovers",
    "pda_responsibility": "I did it on purpose",
    "sys_instrumental_norm_use": "because interfering gets you blamed",
    "pd_decision_conflict": "I genuinely don't know"
  },
  {
    "ce_understood_harm": "My girlfriend would be hit head-on, no warning",
    "pda_responsibility": "because of my choice",
    "ae_welfare_concern": "I care about her too much",
    "sys_instrumental_norm_use": "stick to that mostly when it doesn't cost me much",
    "pd_harm_distress": "I'd still be haunted by the five"
  },
  {
    "pd_harm_distress": "with my stomach in knots",
    "ce_understood_harm": "the train would hit him, kill him or leave him badly broken",
    "ae_welfare_concern": "I care about him more than anyone",
    "sys_instrumental_norm_use": "because it's what keeps others saving me and mine",
    "sys_rule_justification": "social deal of saving the many"
  }
]
